// ═══════════════════════════════════════════════
// EXTRATOR DE MENSAGENS — Evolution API
// Suporta: Texto, Áudio, Imagem, Documento
// ═══════════════════════════════════════════════

const body = $input.first().json.body || $input.first().json;
const data = body.data || body;
const key = data.key || {};
const msg = data.message || {};

const phone = (key.remoteJid || '').replace('@s.whatsapp.net', '').replace('@c.us', '');
const fromMe = key.fromMe || false;
const isGroup = (key.remoteJid || '').includes('@g.us');
const messageId = key.id || '';
const instanceName = body.instance || '';

// Ignorar mensagens próprias e de grupos
if (fromMe || isGroup) return [];

// ── Detectar tipo de mensagem ──
let messageType = 'unknown';
let text = '';
let mediaUrl = '';
let mimeType = '';
let caption = '';

// TEXTO
if (msg.conversation || msg.extendedTextMessage?.text) {
  messageType = 'text';
  text = (msg.conversation || msg.extendedTextMessage?.text || '').trim();
}
// ÁUDIO / VOZ
else if (msg.audioMessage) {
  messageType = 'audio';
  mimeType = msg.audioMessage.mimetype || 'audio/ogg';
  // Evolution API base64 ou URL
  mediaUrl = msg.audioMessage.url || data.message?.base64 || '';
}
// IMAGEM
else if (msg.imageMessage) {
  messageType = 'image';
  mimeType = msg.imageMessage.mimetype || 'image/jpeg';
  caption = msg.imageMessage.caption || '';
  mediaUrl = msg.imageMessage.url || data.message?.base64 || '';
}
// DOCUMENTO
else if (msg.documentMessage) {
  messageType = 'document';
  mimeType = msg.documentMessage.mimetype || '';
  caption = msg.documentMessage.fileName || '';
  mediaUrl = msg.documentMessage.url || '';
}

if (messageType === 'unknown') return [];

return [{
  json: {
    phone,
    messageType,
    text,
    caption,
    mediaUrl,
    mimeType,
    messageId,
    instanceName
  }
}];

const phone = $('Extrair Mensagem').item.json.phone;
return [{ json: { phone, message: '❌ Seu número não está cadastrado no WhatsApp Fin.

Cadastre-se no app e vincule seu número em:
*Configurações → Perfil → Telefone/WhatsApp*' } }];

// Texto direto → prepara contexto para AI Agent
const profile = $('Identificar Usuário').item.json;
const msg = $('Extrair Mensagem').item.json;
const today = new Date();

return [{
  json: {
    phone: msg.phone,
    userId: profile.id,
    userName: profile.first_name || 'Usuário',
    userMessage: msg.text,
    today: today.toLocaleDateString('pt-BR'),
    todayISO: today.toISOString().split('T')[0],
    sessionId: `whatsapp-${msg.phone}`,
    source: 'text'
  }
}];

// Converter base64 do áudio para binary buffer
const response = $input.first().json;
const base64 = response.base64 || response.data?.base64 || '';

if (!base64) {
  return [{ json: { error: 'Áudio não disponível' } }];
}

// Criar buffer binário do base64
const binaryData = Buffer.from(base64, 'base64');

return [{
  json: { ready: true },
  binary: {
    audio: {
      data: base64,
      mimeType: $('Extrair Mensagem').item.json.mimeType || 'audio/ogg',
      fileName: 'voice_message.ogg'
    }
  }
}];

// Áudio transcrito → prepara contexto para AI Agent
const profile = $('Identificar Usuário').item.json;
const msg = $('Extrair Mensagem').item.json;
const transcription = $input.first().json.text || $input.first().json.transcription || 'Não foi possível transcrever o áudio.';
const today = new Date();

return [{
  json: {
    phone: msg.phone,
    userId: profile.id,
    userName: profile.first_name || 'Usuário',
    userMessage: `[Áudio transcrito]: ${transcription}`,
    today: today.toLocaleDateString('pt-BR'),
    todayISO: today.toISOString().split('T')[0],
    sessionId: `whatsapp-${msg.phone}`,
    source: 'audio',
    originalTranscription: transcription
  }
}];

// Analisar imagem com GPT-4o Vision via API direta
const response = $input.first().json;
const base64 = response.base64 || response.data?.base64 || '';
const caption = $('Extrair Mensagem').item.json.caption || '';
const mimeType = $('Extrair Mensagem').item.json.mimeType || 'image/jpeg';

if (!base64) {
  return [{
    json: {
      imageAnalysis: 'Não foi possível baixar a imagem.',
      caption
    }
  }];
}

return [{
  json: {
    base64,
    mimeType,
    caption
  }
}];

