// Imagem analisada → prepara contexto para AI Agent
const profile = $('Identificar Usuário').item.json;
const msg = $('Extrair Mensagem').item.json;
const visionResponse = $input.first().json;
const analysis = visionResponse.choices?.[0]?.message?.content || 'Não foi possível analisar a imagem.';
const caption = msg.caption || '';
const today = new Date();

return [{
  json: {
    phone: msg.phone,
    userId: profile.id,
    userName: profile.first_name || 'Usuário',
    userMessage: `[Imagem recebida]${caption ? ' Legenda: ' + caption : ''}\n\nAnálise da imagem:\n${analysis}\n\nCom base nessa análise, interprete e execute a ação financeira apropriada (registrar despesa, receita, etc). Se não for possível determinar uma ação, apresente as informações extraídas ao usuário.`,
    today: today.toLocaleDateString('pt-BR'),
    todayISO: today.toISOString().split('T')[0],
    sessionId: `whatsapp-${msg.phone}`,
    source: 'image',
    imageAnalysis: analysis
  }
}];

// Tipo não suportado
const phone = $('Extrair Mensagem').item.json.phone;
return [{ json: { phone, message: '📎 Ainda não consigo processar esse tipo de arquivo.\n\nEnvie *texto*, *áudio* ou *foto* (recibos, comprovantes)! 📸' } }];

const phone = $json.phone || $('Extrair Mensagem').item.json.phone;
const agentOutput = $input.first().json.output || $input.first().json.text || 'Desculpe, não consegui processar. Tente novamente.';
return [{ json: { phone, message: agentOutput } }];

const profile = $('Buscar Usuários Alertas').item.json;
const accounts = $('Contas (Alertas)').all().map(i => i.json);
const fixedTxs = $('Fixas (Alertas)').all().map(i => i.json);
const budgets = $('Orçamentos (Alertas)').all().map(i => i.json);
const transactions = $('Transações (Alertas)').all().map(i => i.json);
const alerts = [];
const today = new Date();
const currentDay = today.getDate();

if (profile.notify_low_balance) {
  const threshold = Number(profile.low_balance_threshold) || 100;
  for (const acc of accounts) {
    const bal = Number(acc.balance);
    if (bal < threshold) alerts.push(`⚠️ *Saldo baixo*: "${acc.name}" com R$ ${bal.toFixed(2)} (limite: R$ ${threshold.toFixed(2)})`);
  }
}
if (profile.notify_fixed_due) {
  const days = Number(profile.fixed_due_days) || 3;
  for (const ft of fixedTxs) {
    const d = Number(ft.day_of_month) - currentDay;
    if (d < 0 || d > days) continue;
    alerts.push(`${ft.type==='expense'?'💸':'💰'} *${ft.description}* vence ${d===0?'HOJE':`em ${d} dia(s)`} — R$ ${Number(ft.amount).toFixed(2)}`);
  }
}
if (profile.notify_budget_alert) {
  const pct = (Number(profile.budget_alert_percentage)||80)/100;
  for (const b of budgets) {
    const spent = transactions.filter(t=>t.category_id===b.category_id).reduce((s,t)=>s+Number(t.amount),0);
    const lim = Number(b.monthly_limit); if(lim<=0) continue;
    if(spent/lim >= pct) alerts.push(`🔴 *Orçamento*: Gastou ${(spent/lim*100).toFixed(0)}% (R$ ${spent.toFixed(2)} de R$ ${lim.toFixed(2)})`);
  }
}
if (!alerts.length) return [];
const h = today.getHours();
const g = h<12?'Bom dia':h<18?'Boa tarde':'Boa noite';
return [{json:{phone:profile.phone,message:[`${g}, ${profile.first_name||'Usuário'}! 📊`,'','Seus alertas financeiros:','',...alerts,'','---',`_WhatsApp Fin • ${today.toLocaleDateString('pt-BR')}_`].join('\n'),alertCount:alerts.length}}];
